/*------------------------------------------------------------------------------------------------------------------------------------------------------------------------AUTOR: ROBERTO RECIFEDATA : 24/05/2023DESCRICAO: CONFERENCIA CONTABIL------------------------------------------------------------------------------------------------------------------------------------------------------------------------SP_CONFERENCIA_CONTABIL '20230401','20230405'------------------------------------------------------------------------------------------------------------------------------------------------------------------------DROP PROCEDURE SP_CONFERENCIA_CONTABIL------------------------------------------------------------------------------------------------------------------------------------------------------------------------*/CREATE PROCEDURE [dbo].[SP_CONFERENCIA_CONTABIL](	@MV_PAR01		VARCHAR(08),	@MV_PAR02		VARCHAR(08))AS------------------------------------------------------------------------------------------------------------------------------------------------------------------------SET NOCOUNT ON ------------------------------------------------------------------------------------------------------------------------------------------------------------------------SELECT	CONVERT(VARCHAR(10),CONVERT(DATETIME,CT2_DATA),103) 'DATA',		CT2_LOTE+CT2_SBLOTE+CT2_DOC+CT2_LINHA 'LOTE/SUB/DOC/LINHA',		'D/C'=CASE WHEN CT2_DC='1' THEN 'DEBITO' WHEN CT2_DC='2' THEN 'CREDITO' ELSE 'PARTIDA' END,		CT2_DEBITO 'CONTA DEB',		'DESC.DEBITO'=ISNULL((SELECT CT1_DESC01 FROM CT1010 WHERE CT1_FILIAL='01' AND CT1_CONTA=CT2_DEBITO AND D_E_L_E_T_<>'*'),''),		CT2_CREDIT 'CONTA CRE',		'DESC.CREDITO'=ISNULL((SELECT CT1_DESC01 FROM CT1010 WHERE CT1_FILIAL='01' AND CT1_CONTA=CT2_CREDIT AND D_E_L_E_T_<>'*'),''),		CONVERT(NUMERIC(12,2),CT2_VALOR) 'VALOR R$',		CT2_HIST 'HISTORICO',		CT2_CCD 'C.C DEB',		'DESC.C.C DEB'=ISNULL((SELECT CTT_DESC01 FROM CTT010 WHERE CTT_FILIAL='0101' AND CTT_CUSTO=CT2_CCD AND D_E_L_E_T_<>'*'),''),		CT2_CCC 'C.C CRE',		'DESC.C.C CRE'=ISNULL((SELECT CTT_DESC01 FROM CTT010 WHERE CTT_FILIAL='0101' AND CTT_CUSTO=CT2_CCC AND D_E_L_E_T_<>'*'),''),		CT2_ITEMD 'ITEM DEB',		CT2_ITEMC 'ITEM CRE',		CT2_ORIGEM 'ORIGEM'FROM	CT2010WHERE	CT2_FILIAL='0101'		AND CT2_DATA BETWEEN @MV_PAR01 AND @MV_PAR02		AND D_E_L_E_T_<>'*' ORDER BY CONVERT(DATETIME,CT2_DATA),CT2_LOTE+CT2_SBLOTE+CT2_DOC+CT2_LINHA------------------------------------------------------------------------------------------------------------------------------------------------------------------------SET NOCOUNT OFF-----------------------------------------------------------------------------------------------------------------------------------------------------------------------